<tr><td>Port Aransas</td><td>Nueces</td><td>Yes</td><td>NFIP only, not in CRS</td></tr>
<tr><td>Portland</td><td>San Patricio</td><td>Yes</td><td>NFIP only, not in CRS</td></tr>
